import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Security","description":"","frontmatter":{},"headers":[],"relativePath":"guide/security.md","filePath":"guide/security.md","lastUpdated":1786899786000}`),a={name:`guide/security.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to “Security”">​</a></h1><p>This page is the prose version of the repository&#39;s <a href="https://github.com/ni-c/wg-easy-mcp/blob/main/SECURITY.md" target="_blank" rel="noreferrer">SECURITY.md</a>. For reporting a vulnerability, use <a href="https://github.com/ni-c/wg-easy-mcp/security/advisories/new" target="_blank" rel="noreferrer">private vulnerability reporting</a> — never a public issue.</p><h2 id="what-the-credentials-grant" tabindex="-1">What the credentials grant <a class="header-anchor" href="#what-the-credentials-grant" aria-label="Permalink to “What the credentials grant”">​</a></h2><p>The server authenticates with a wg-easy <strong>admin</strong> login. wg-easy has no read-only role, so there is no configuration in which this server holds less than full VPN administration. Concretely, anything able to read this process&#39;s environment can:</p><ul><li>create, disable and delete peers,</li><li>download any peer&#39;s configuration file and QR code, both of which contain that peer&#39;s <strong>private key</strong>,</li><li>mint one-time links that let an unauthenticated visitor download a config.</li></ul><p>Treat the process environment, the MCP client&#39;s config file and the tool output as three copies of the same secret.</p><h2 id="who-decides-what-gets-called" tabindex="-1">Who decides what gets called <a class="header-anchor" href="#who-decides-what-gets-called" aria-label="Permalink to “Who decides what gets called”">​</a></h2><p>The MCP client does. This server enforces the confirmation handshake and the redaction rules described below, but it cannot tell a legitimate request from one a model was talked into. Connect it only to clients you would trust with the VPN itself.</p><h2 id="guard-rails-in-the-server" tabindex="-1">Guard rails in the server <a class="header-anchor" href="#guard-rails-in-the-server" aria-label="Permalink to “Guard rails in the server”">​</a></h2><h3 id="deleting-takes-two-calls" tabindex="-1">Deleting takes two calls <a class="header-anchor" href="#deleting-takes-two-calls" aria-label="Permalink to “Deleting takes two calls”">​</a></h3><p><code>delete_client</code> will not delete on the first call. It verifies the client exists, then returns a random 128-bit token that is <strong>bound to that client ID</strong> and valid for <strong>five minutes</strong>. Only a second call carrying that exact token deletes.</p><p>The reason it is a token and not a <code>confirm: true</code> flag: a boolean is something the model can set by itself on the first call, including when it has been steered there by text it read somewhere. A random value that only exists in a previous tool response cannot be produced that way.</p><p>The confirmation message quotes the client <strong>ID and nothing else</strong> — never the client&#39;s name — because that text is read by a model and a name is attacker-supplied.</p><h3 id="admin-secrets-are-redacted" tabindex="-1">Admin secrets are redacted <a class="header-anchor" href="#admin-secrets-are-redacted" aria-label="Permalink to “Admin secrets are redacted”">​</a></h3><p><code>get_server_info</code> reads wg-easy&#39;s admin endpoints, which return the server configuration. Keys named <code>privateKey</code>, <code>preSharedKey</code>, <code>password</code>, <code>passwordHash</code>, <code>sessionSecret</code> or anything starting with <code>totp</code> are replaced with <code>[redacted]</code> at every nesting level before the result is returned.</p><p>Note the deliberate asymmetry: <code>get_client_config</code> and <code>get_client_qrcode</code> return private keys <strong>unredacted</strong>, because handing a peer its configuration is the point of those tools. Their descriptions say so.</p><h3 id="upstream-content-is-marked-untrusted" tabindex="-1">Upstream content is marked untrusted <a class="header-anchor" href="#upstream-content-is-marked-untrusted" aria-label="Permalink to “Upstream content is marked untrusted”">​</a></h3><p>Client names, DNS entries and endpoints are free-form strings chosen by whoever administers the VPN. Everything the wg-easy API returns is prefixed with an explicit untrusted-data marker telling the model to treat the block as data to report rather than instructions to follow, and is capped at 60 000 characters so a single oversized field cannot flood the context.</p><h3 id="transport" tabindex="-1">Transport <a class="header-anchor" href="#transport" aria-label="Permalink to “Transport”">​</a></h3><ul><li>Requests carry a <strong>15-second timeout</strong> and <code>redirect: &#39;error&#39;</code> — following a redirect would hand the <code>Authorization</code> header to whatever host it points at.</li><li><code>WG_EASY_INSECURE_TLS</code> is a <strong>scoped undici dispatcher</strong>, so relaxed certificate validation applies to the wg-easy connection only and never process-wide.</li><li>A URL carrying embedded credentials is rejected at startup rather than logged.</li><li>Credentials are removed from <code>process.env</code> after the config is read.</li></ul><h3 id="error-output" tabindex="-1">Error output <a class="header-anchor" href="#error-output" aria-label="Permalink to “Error output”">​</a></h3><p>Upstream error bodies are truncated to 2 000 characters, and HTML error pages — the usual output of a reverse proxy or WAF — are dropped entirely instead of being pasted into the model&#39;s context.</p><h2 id="deployment-recommendations" tabindex="-1">Deployment recommendations <a class="header-anchor" href="#deployment-recommendations" aria-label="Permalink to “Deployment recommendations”">​</a></h2><ul><li>Keep the wg-easy admin UI reachable only from trusted networks. The MCP server uses the same URL and inherits exactly that exposure.</li><li>Give the server its own admin account where wg-easy supports multiple users, and rotate its password when you revoke access.</li><li>Pass credentials through the client&#39;s <code>env</code> block — not a command line, where they land in shell history and <code>ps</code>.</li><li>Prefer an internal CA over <code>WG_EASY_INSECURE_TLS</code>.</li></ul><h2 id="supply-chain" tabindex="-1">Supply chain <a class="header-anchor" href="#supply-chain" aria-label="Permalink to “Supply chain”">​</a></h2><p>Releases are published to npm via <a href="https://docs.npmjs.com/trusted-publishers" target="_blank" rel="noreferrer">Trusted Publishing</a> with <a href="https://docs.npmjs.com/generating-provenance-statements" target="_blank" rel="noreferrer">provenance</a> — no long-lived token exists to leak. Container images ship an SBOM and <code>provenance: mode=max</code>. CI runs <code>npm audit</code>, CodeQL and a Trivy scan of the image on every push and once a week; the runtime image contains no npm at all.</p>`,26)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};